/**
 * Mini schemastery value surface for the NodeWorkerJsHost overlay.
 *
 * The real @deepseek-ai/schemastery is an ESM build with a large surface; the
 * agent-fusion overlays value-import the `z` root and construct Config /
 * settings schemas from `z.object`/`z.boolean`/`z.string`/`z.array`/`z.dict`
 * with chained `.default()`/`.step()`/`.min()`/`.role()`. This overlay supplies
 * exactly the surface the bridged packages touch, AND the schema-node shape the
 * real @deepseek-ai/dsh-settings walks at runtime:
 *
 *   - a schema IS callable (`schema(value)` validates + normalizes, like
 *     `schema.parse(value)` — the real dsh-settings `resolve()` calls the
 *     schema directly);
 *   - `.type` / `.meta` / `.dict` (object properties) / `.inner` (array/dict
 *     item) — the fields @deepseek-ai/dsh-settings/redact walks for
 *     `role('secret')` positions;
 *   - `.toJSON()` — the shape the real dsh-settings `describe()` serializes for
 *     configuration surfaces;
 *   - `.role(text)` — marks a node with `meta.role = 'secret'` (etc.).
 *
 * Validation is intentionally light on this host (config is validated by the
 * owning service); the overlay is faithful on SHAPE, not on error messages.
 *
 * @module @deepseek-ai/schemastery
 */

/**
 * Build one schema node: a CALLABLE function (`schema(value)` → normalized
 * value) carrying the schemastery node surface (`.type`, `.meta`, `.dict`,
 * `.inner`, `.toJSON()`) plus the chained builder methods.
 * @param type - schemastery node type ('object' | 'array' | 'dict' | 'number' | ...).
 * @param build - optional closure configuring the node (shape / item).
 * @returns the callable schema node.
 */
function makeSchema(type, build) {
  const s = (value, _options) => s.parse(value)
  s.__schemastery = true
  s.type = type
  s.meta = {}
  s._default = undefined
  s._shape = undefined
  s._item = undefined
  // Chained builders (faithful; validation is the owning service's job).
  s.default = (v) => { s._default = v; return s }
  s.optional = () => s
  s.required = () => s
  s.step = () => s
  s.min = () => s
  s.max = () => s
  s.hidden = () => s
  // role('secret') → meta.role, exactly where the dsh-settings redactor looks.
  s.role = (role, extra) => { s.meta.role = role; if (extra !== undefined) s.meta.extra = extra; return s }
  // Default parse: fill a default for null/undefined input, else pass through.
  s.parse = (v) => {
    if (s._default !== undefined && (v === undefined || v === null)) return s._default
    return v
  }
  // Serialize the node shape for configuration surfaces (dsh-settings describe).
  s.toJSON = () => {
    const out = { type: s.type }
    if (s._shape !== undefined) {
      out.properties = {}
      for (const [k, sub] of Object.entries(s._shape)) out.properties[k] = sub.toJSON()
    }
    if (s._item !== undefined) out.inner = s._item.toJSON()
    if (Object.keys(s.meta).length > 0) out.meta = { ...s.meta }
    return out
  }
  if (build) build(s)
  return s
}

const z = {
  object(shape) {
    const s = makeSchema('object', (node) => {
      node._shape = shape
      // The redactor (dsh-settings/redact) reads `dict` for object properties.
      node.dict = shape
      node.strict = () => s
      node.parse = (v) => {
        if (s._default !== undefined && (v === undefined || v === null)) return s._default
        const input = v == null ? {} : v
        const out = {}
        for (const [k, sub] of Object.entries(shape)) {
          const parsed = sub.parse(input[k])
          // Omit genuinely-absent fields (no default): matches the sparse
          // section semantics the settings seam assumes on its resolved values.
          if (parsed !== undefined) out[k] = parsed
        }
        return out
      }
      node.merge = (...schemas) => {
        const merged = {}
        for (const schema of [s, ...schemas]) {
          if (schema && schema._shape) Object.assign(merged, schema._shape)
        }
        return z.object(merged)
      }
    })
    return s
  },
  array(item) {
    return makeSchema('array', (node) => {
      node._item = item
      node.inner = item
      node.parse = (v) => {
        if (node._default !== undefined && (v === undefined || v === null)) return node._default
        if (v == null) return undefined
        return v.map((x) => item.parse(x))
      }
    })
  },
  dict(item) {
    return makeSchema('dict', (node) => {
      node._item = item
      node.inner = item
      node.parse = (v) => {
        if (node._default !== undefined && (v === undefined || v === null)) return node._default
        if (v == null) return undefined
        const out = {}
        for (const [k, entry] of Object.entries(v)) {
          const parsed = item.parse(entry)
          if (parsed !== undefined) out[k] = parsed
        }
        return out
      }
    })
  },
  boolean() { return makeSchema('boolean') },
  number() { return makeSchema('number') },
  string() { return makeSchema('string') },
  // Literal schema: parse yields the const value when the input equals it
  // (absent input without a default stays undefined). M5 llm ports use
  // `z.const('normal').required()` for retry-policy `mode`.
  const(value) {
    return makeSchema('const', (node) => {
      node.parse = (v) => {
        if (node._default !== undefined && (v === undefined || v === null)) return node._default
        if (v === undefined || v === null) return undefined
        return v === value ? value : undefined
      }
      node.toJSON = () => ({ type: 'const', value })
    })
  },
  // Union schema: try each member (a schema or a bare literal value treated as
  // a const); the first defined result wins. Mirrors the real schemastery
  // union's resolve-first-that-validates contract.
  union(list) {
    return makeSchema('union', (node) => {
      const members = list.map((member) =>
        (member != null && typeof member === 'object' && typeof member.parse === 'function')
          ? member
          : z.const(member))
      node.list = members
      node.parse = (v) => {
        if (node._default !== undefined && (v === undefined || v === null)) return node._default
        if (v === undefined || v === null) return undefined
        for (const member of members) {
          const parsed = member.parse(v)
          if (parsed !== undefined) return parsed
        }
        return undefined
      }
      node.toJSON = () => ({ type: 'union', list: members.map((m) => m.toJSON()) })
    })
  },
}

export default z
